// Eight sources, four subgroups, two effect returns, and a metered stereo output.
window.createLotusSignalEngine=function(ctx,channels,master,output){
 const linear=v=>v<=0?0:Math.pow(v/100,1.4),db=v=>v>1e-6?20*Math.log10(v):-Infinity;
 const meter=node=>{const analyser=ctx.createAnalyser();analyser.fftSize=2048;node.connect(analyser);return{analyser,data:new Float32Array(2048),rms:0,peak:0,peakDb:-Infinity,rmsDb:-Infinity,vu:0}};
 const buses=['DRUMS','BASS','MUSIC','FX','ROOM','DELAY'].map((name,i)=>{const gain=ctx.createGain();gain.gain.value=i>3?.5:1;gain.connect(master);return{id:name.toLowerCase(),name,value:i>3?61:100,gain,meter:meter(gain)}});
 const reverb=ctx.createConvolver(),ir=ctx.createBuffer(2,Math.floor(ctx.sampleRate*1.7),ctx.sampleRate);for(let ch=0;ch<2;ch++){const a=ir.getChannelData(ch);for(let i=0;i<a.length;i++)a[i]=(Math.random()*2-1)*Math.pow(1-i/a.length,3)*.24}reverb.buffer=ir;reverb.connect(buses[4].gain);
 const delay=ctx.createDelay(2),feedback=ctx.createGain(),damping=ctx.createBiquadFilter();delay.delayTime.value=60/104*.75;feedback.gain.value=.27;damping.type='lowpass';damping.frequency.value=4200;delay.connect(damping).connect(feedback).connect(delay);delay.connect(buses[5].gain);
 const routes=[0,0,0,1,2,2,2,3],strips=channels.map((c,i)=>{const input=ctx.createGain(),hpf=ctx.createBiquadFilter(),low=ctx.createBiquadFilter(),mid=ctx.createBiquadFilter(),high=ctx.createBiquadFilter(),fader=ctx.createGain(),pan=ctx.createStereoPanner(),room=ctx.createGain(),echo=ctx.createGain();hpf.type='highpass';hpf.frequency.value=c.hpf;hpf.Q.value=.707;pan.pan.value=c.pan;room.gain.value=c.room<=-60?0:Math.pow(10,c.room/20);echo.gain.value=c.delay<=-60?0:Math.pow(10,c.delay/20);low.gain.value=c.low;mid.gain.value=c.mid;high.gain.value=c.high;low.type='lowshelf';low.frequency.value=120;mid.type='peaking';mid.frequency.value=1200;mid.Q.value=.8;high.type='highshelf';high.frequency.value=8000;input.connect(hpf).connect(low).connect(mid).connect(high).connect(fader).connect(pan).connect(buses[routes[i]].gain);pan.connect(room).connect(reverb);pan.connect(echo).connect(delay);return{input,fader,hpf,low,mid,high,pan,room,echo,meter:meter(pan)}});
 const splitter=ctx.createChannelSplitter(2);output.connect(splitter);const l=ctx.createGain(),r=ctx.createGain();splitter.connect(l,0);splitter.connect(r,1);const stereo=[meter(l),meter(r)],all=[...strips.map(s=>s.meter),...buses.map(b=>b.meter),...stereo];let last=-1;
 function update(){channels.forEach((c,i)=>{const s=strips[i],at=ctx.currentTime;s.hpf.frequency.setTargetAtTime(c.hpf,at,.025);for(const k of ['low','mid','high'])s[k].gain.setTargetAtTime(c[k],at,.025);s.pan.pan.setTargetAtTime(c.pan,at,.025);s.room.gain.setTargetAtTime(c.room<=-60?0:Math.pow(10,c.room/20),at,.03);s.echo.gain.setTargetAtTime(c.delay<=-60?0:Math.pow(10,c.delay/20),at,.03)})}
 function read(now=performance.now()){if(now-last<30)return frame;const dt=Math.min(.2,Math.max(.016,(now-last)/1000));last=now;all.forEach(m=>{m.analyser.getFloatTimeDomainData(m.data);let sum=0,peak=0;for(const v of m.data){sum+=v*v;peak=Math.max(peak,Math.abs(v))}m.rms=Math.sqrt(sum/m.data.length);m.peak=peak;m.peakDb=db(peak);m.rmsDb=db(m.rms);m.vu+=(m.rms-m.vu)*(1-Math.exp(-dt/.3))});return frame}
 const frame={channels:strips.map(s=>s.meter),buses:buses.map(b=>b.meter),master:stereo};
 function setBus(id,value){const b=buses.find(b=>b.id===id);if(!b||!Number.isFinite(value)||value<0||value>100)throw new Error('Invalid bus level');b.value=value;b.gain.gain.setTargetAtTime(linear(value),ctx.currentTime,.025)}
 update();return{inputs:strips.map(s=>s.input),gains:strips.map(s=>s.fader),buses,read,update,setBus,routes};
};
